// What the engine and the dashboard need from the hourly weather rows of ONE field.
// "Next 24 h" = values stamped in (now, now + 24 h] (docs/formulas.md). A missing value is never 0.

export interface WeatherRow {
  observed_at: string;
  air_temperature_c: number | null;
  precipitation_mm: number | null;
  rain_probability_pct: number | null;
  et0_mm: number | null;
}

export interface WeatherSummary {
  /** latest hourly row at or before now */
  airTemperatureC: number | null;
  next24h: {
    hours: number;
    /** sum of the hourly precipitation. null when no value exists at all */
    precipitationMm: number | null;
    /** true only when all 24 hours have a value: otherwise the sum may be too low and must not be trusted as "no rain" */
    precipitationComplete: boolean;
    maxRainProbabilityPct: number | null;
    maxAirTemperatureC: number | null;
    firstRainAt: string | null;
  };
}

const HOUR = 3_600_000;

export function summarizeWeather(rows: WeatherRow[], nowMs: number): WeatherSummary {
  const sorted = [...rows].sort((a, b) => Date.parse(a.observed_at) - Date.parse(b.observed_at));

  let airTemperatureC: number | null = null;
  for (const r of sorted) {
    if (Date.parse(r.observed_at) <= nowMs) airTemperatureC = r.air_temperature_c;
  }

  const win = sorted.filter((r) => {
    const t = Date.parse(r.observed_at);
    return t > nowMs && t <= nowMs + 24 * HOUR;
  });

  const precip = win.map((r) => r.precipitation_mm).filter((v): v is number => v !== null);
  const probs = win.map((r) => r.rain_probability_pct).filter((v): v is number => v !== null);
  const temps = win.map((r) => r.air_temperature_c).filter((v): v is number => v !== null);
  const firstRain = win.find((r) => (r.precipitation_mm ?? 0) > 0);

  return {
    airTemperatureC,
    next24h: {
      hours: win.length,
      precipitationMm: precip.length ? precip.reduce((s, v) => s + v, 0) : null,
      precipitationComplete: win.length === 24 && precip.length === 24,
      maxRainProbabilityPct: probs.length ? Math.max(...probs) : null,
      maxAirTemperatureC: temps.length ? Math.max(...temps) : null,
      firstRainAt: firstRain ? firstRain.observed_at : null,
    },
  };
}
